import 'dart:convert';
import 'dart:ffi';
import 'dart:io';

/// Resolve an explicit runtime, or the host asset generated by Flutter's hooks.
/// Never use an Android asset just because an APK was built more recently.
String resolvePdfiumTestLibrary({
  String? configuredPath,
  Directory? hooksDirectory,
  String? targetOs,
  String? targetArchitecture,
}) {
  final explicit = configuredPath?.trim();
  if (explicit != null && explicit.isNotEmpty) {
    final library = File(explicit).absolute;
    if (!library.existsSync()) {
      throw StateError('PDFIUM_PATH does not exist: ${library.path}');
    }
    return library.path;
  }

  final hooks =
      hooksDirectory ?? Directory('.dart_tool/hooks_runner/pdfium_dart');
  final os = targetOs ?? Platform.operatingSystem;
  final architecture =
      targetArchitecture ?? Abi.current().toString().split('_').last;
  if (hooks.existsSync()) {
    final directories = hooks.listSync().whereType<Directory>().toList()
      ..sort((a, b) => b.statSync().modified.compareTo(a.statSync().modified));
    for (final directory in directories) {
      try {
        final input = jsonDecode(
          File('${directory.path}/input.json').readAsStringSync(),
        );
        final output = jsonDecode(
          File('${directory.path}/output.json').readAsStringSync(),
        );
        final code = input['config']?['extensions']?['code_assets'];
        if (input['package_name'] != 'pdfium_dart' ||
            code?['target_os'] != os ||
            code?['target_architecture'] != architecture ||
            output['status'] != 'success') {
          continue;
        }
        for (final asset in output['assets'] as List) {
          final encoding = asset['encoding'];
          if (encoding?['id'] != 'package:pdfium_dart/libpdfium') continue;
          final file = encoding?['file'];
          if (file is String && File(file).existsSync()) {
            return File(file).absolute.path;
          }
        }
      } on FileSystemException {
        // Another platform's hook may be incomplete or cleaned by Flutter.
      } on FormatException {
        // Ignore incomplete build metadata; report setup instructions below.
      }
    }
  }
  throw StateError(
    'No host PDFium library found for $os-$architecture. '
    'Run flutter test with native build hooks enabled, or set PDFIUM_PATH '
    'to a compatible host library (not an Android library). '
    'Do not copy libraries into the Flutter SDK.',
  );
}
